html:
{%- macro v(value) -%}{{ (value or "") | e }}{%- endmacro -%}
{%- macro money(value) -%}{{ "{:,.2f}".format((value or 0) | float) }}{%- endmacro -%}
{%- macro num(value) -%}{{ "{:g}".format((value or 0) | float) }}{%- endmacro -%}
{%- macro shs(value) -%}{{ "{:,.0f}".format((value or 0) | float) }}{%- endmacro -%}
{%- set logo = frappe.db.get_single_value("HRMS Addon Branding", "company_logo") -%}
{%- set p = pay_slip(doc) -%}
{%- set ns = namespace(hours=False) -%}
{%- for line in p.payments %}{% if line.hours %}{% set ns.hours = True %}{% endif %}{% endfor -%}
<style>
/* Luuka's pay slip: what their paper slip says, in its order, at its size: a
   270pt by 600pt box with nothing under 8pt. The colours are their logo's.
   Every figure and heading stays dark on a light tint, so a slip printed
   without background graphics still reads.
   No table: Frappe's print styles pad every cell and grey every heading,
   whatever a format says. Every rule here is written under .print-format and
   marked !important where a print style sets the same thing on a div or a
   span. Floats and widths in %, for wkhtmltopdf has no flex or grid. */
.print-format .lpl-slip, .print-format .lpl-slip div, .print-format .lpl-slip span {
  font-family: Arial, Helvetica, "Liberation Sans", sans-serif !important; font-size: 8pt !important;
  line-height: 11pt !important; font-weight: normal; color: #1f2937 !important; box-sizing: border-box; margin: 0;
  padding: 0; letter-spacing: 0; text-align: left; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
.print-format .lpl-slip { width: 270pt; min-height: 600pt; border: 0.75pt solid #b7c7df; border-top: 4pt solid #3a66ad;
  border-radius: 3pt; padding: 10pt 14pt; background: #fff; }

.print-format .lpl-slip .s-head { overflow: hidden; padding-bottom: 7pt; }
.print-format .lpl-slip .s-brand { float: left; width: 50%; }
.print-format .lpl-slip .s-brand img { display: block; max-width: 88pt; max-height: 34pt; }
.print-format .lpl-slip .s-company { color: #667085 !important; padding-top: 2pt; text-transform: uppercase; }
.print-format .lpl-slip .s-title { float: right; width: 50%; }
.print-format .lpl-slip .s-big { font-size: 15pt !important; line-height: 19pt !important; font-weight: bold;
  color: #24457f !important; letter-spacing: 1pt; text-align: right; }
.print-format .lpl-slip .s-month { font-size: 9pt !important; font-weight: bold; color: #3a66ad !important; text-align: right; }

.print-format .lpl-slip .s-check { border: 0.75pt solid #d97706; border-radius: 2pt; background: #fff7ed;
  color: #92400e !important; font-weight: bold; text-align: center; letter-spacing: 0.5pt; padding: 2pt 0;
  margin: 0 0 5pt; }

.print-format .lpl-slip .s-who { background: #f3f6fb; border: 0.5pt solid #e0e8f3; border-radius: 3pt; padding: 5pt 8pt 3pt; }
.print-format .lpl-slip .s-i { overflow: hidden; padding-bottom: 2pt; }
.print-format .lpl-slip .s-k { float: left; width: 31%; color: #667085 !important; }
.print-format .lpl-slip .s-v { float: left; width: 69%; font-weight: bold; text-transform: uppercase; }

.print-format .lpl-slip .s-money { padding-top: 9pt; }
.print-format .lpl-slip .s-r { overflow: hidden; padding: 1.5pt 4pt; border-bottom: 0.5pt solid #e7ecf3; }
.print-format .lpl-slip .s-th { padding: 0 4pt 2pt; border-bottom: 1.25pt solid #3a66ad; }
.print-format .lpl-slip .s-th div { font-weight: bold; color: #24457f !important; }
.print-format .lpl-slip .s-n { float: left; width: 60%; }
.print-format .lpl-slip .s-a { float: right; width: 40%; text-align: right; white-space: nowrap; }
.print-format .lpl-slip .s-hours .s-n { width: 50%; }
.print-format .lpl-slip .s-hours .s-a { float: left; width: 31%; }
.print-format .lpl-slip .s-h { float: left; width: 19%; text-align: right; white-space: nowrap; }
.print-format .lpl-slip .s-total { background: #eef3fa; border-bottom: 0; border-radius: 2pt; margin-top: 2pt; padding: 2.5pt 4pt; }
.print-format .lpl-slip .s-total div { font-weight: bold; color: #24457f !important; }

.print-format .lpl-slip .s-net { margin-top: 9pt; padding: 5pt 8pt; background: #eef3fa; border: 0.75pt solid #3a66ad; border-radius: 3pt; }
.print-format .lpl-slip .s-l { overflow: hidden; }
.print-format .lpl-slip .s-nk { float: left; width: 45%; font-weight: bold; color: #24457f !important; }
.print-format .lpl-slip .s-nv { float: right; width: 55%; text-align: right; font-weight: bold; }
.print-format .lpl-slip .s-round .s-nk { line-height: 19pt !important; }
.print-format .lpl-slip .s-round .s-nv { font-size: 14pt !important; line-height: 19pt !important; color: #24457f !important; }

.print-format .lpl-slip .s-by { overflow: hidden; padding: 6pt 4pt 0; }
.print-format .lpl-slip .s-by .s-k { width: 27%; }
.print-format .lpl-slip .s-by .s-v { width: 73%; }

.print-format .lpl-slip .s-days { margin-top: 6pt; border-top: 0.5pt solid #d5e0ef; padding-top: 6pt; }
.print-format .lpl-slip .s-dl { overflow: hidden; padding-bottom: 4pt; }
.print-format .lpl-slip .s-day { float: left; width: 33.33%; border-left: 0.5pt solid #d5e0ef; padding: 0 2pt; }
.print-format .lpl-slip .s-day.s-first { border-left: 0; }
.print-format .lpl-slip .s-dv { font-size: 9pt !important; line-height: 13pt !important; font-weight: bold; text-align: center; color: #24457f !important; }
.print-format .lpl-slip .s-dk { color: #667085 !important; text-align: center; }
</style>
<div class="lpl-slip">
<div class="s-head">
<div class="s-brand">{% if logo %}<img src="{{ logo }}">{% endif %}<div class="s-company">{{ v(p.company) }}</div></div>
<div class="s-title"><div class="s-big">PAY SLIP</div><div class="s-month">{{ v(p.slip_for) }}</div></div>
</div>
{%- if doc.docstatus == 0 %}
<div class="s-check">FOR CHECKING, NOT YET PAID</div>
{%- endif %}
<div class="s-who">
<div class="s-i"><div class="s-k">NAME</div><div class="s-v">{{ v(p.employee_name) }}</div></div>
<div class="s-i"><div class="s-k">DEPT</div><div class="s-v">{{ v(p.department) }}</div></div>
<div class="s-i"><div class="s-k">PAYROLL NO.</div><div class="s-v">{{ v(p.payroll_no) }}</div></div>
<div class="s-i"><div class="s-k">DESIGNATION</div><div class="s-v">{{ v(p.designation) }}</div></div>
<div class="s-i"><div class="s-k">CATEGORY</div><div class="s-v">{{ v(p.category) }}</div></div>
{%- if p.section %}
<div class="s-i"><div class="s-k">SECTION</div><div class="s-v">{{ v(p.section) }}</div></div>
{%- endif %}
</div>
<div class="s-money{% if ns.hours %} s-hours{% endif %}">
<div class="s-r s-th"><div class="s-n">PAYMENTS</div><div class="s-a">AMOUNT{% if p.currency %} {{ v(p.currency) }}{% endif %}</div>{% if ns.hours %}<div class="s-h">HOURS</div>{% endif %}</div>
{%- for line in p.payments %}
<div class="s-r"><div class="s-n">{{ v(line.name) }}</div><div class="s-a">{{ money(line.amount) }}</div>{% if ns.hours %}<div class="s-h">{% if line.hours %}{{ num(line.hours) }}{% else %}&nbsp;{% endif %}</div>{% endif %}</div>
{%- endfor %}
<div class="s-r s-total"><div class="s-n">{% if p.ugx %}TOTAL{% else %}GROSS PAY{% endif %}</div><div class="s-a">{{ money(p.gross) }}</div>{% if ns.hours %}<div class="s-h">&nbsp;</div>{% endif %}</div>
</div>
{%- if not p.ugx %}
<div class="s-money{% if ns.hours %} s-hours{% endif %}">
<div class="s-r s-th"><div class="s-n">DEDUCTIONS</div><div class="s-a">AMOUNT{% if p.currency %} {{ v(p.currency) }}{% endif %}</div>{% if ns.hours %}<div class="s-h">&nbsp;</div>{% endif %}</div>
{%- for line in p.deductions %}
<div class="s-r"><div class="s-n">{{ v(line.name) }}</div><div class="s-a">{{ money(line.amount) }}</div>{% if ns.hours %}<div class="s-h">&nbsp;</div>{% endif %}</div>
{%- endfor %}
<div class="s-r s-total"><div class="s-n">TOTAL</div><div class="s-a">{{ money(p.total_deductions) }}</div>{% if ns.hours %}<div class="s-h">&nbsp;</div>{% endif %}</div>
</div>
<div class="s-net">
<div class="s-l"><div class="s-nk">NET PAY</div><div class="s-nv">{{ money(p.net) }}</div></div>
<div class="s-l s-round"><div class="s-nk">NET PAY R/o</div><div class="s-nv">{{ money(p.rounded) }}</div></div>
</div>
{%- if p.payment_by %}
<div class="s-by"><div class="s-k">PAYMENT BY</div><div class="s-v">{{ v(p.payment_by) }}</div></div>
{%- endif %}
{%- endif %}
<div class="s-days">
<div class="s-dl">
<div class="s-day s-first"><div class="s-dv">{{ num(p.paid_days) }}</div><div class="s-dk">Paid Days</div></div>
{%- if p.hourly %}
<div class="s-day"><div class="s-dv">{{ num(p.hours_worked) }}</div><div class="s-dk">Hours Worked</div></div>
<div class="s-day"><div class="s-dv">{{ num(p.overtime_hours) }}</div><div class="s-dk">Overtime Hours</div></div>
{%- else %}
<div class="s-day"><div class="s-dv">{{ num(p.working_days) }}</div><div class="s-dk">Working Days</div></div>
<div class="s-day"><div class="s-dv">{{ num(p.holidays) }}</div><div class="s-dk">Holidays</div></div>
{%- endif %}
</div>
<div class="s-dl">
<div class="s-day s-first"><div class="s-dv">{{ money(p.absent_amount) }}</div><div class="s-dk">Absent Amount</div></div>
<div class="s-day"><div class="s-dv">{{ num(p.leave_taken) }}</div><div class="s-dk">Leave Taken</div></div>
<div class="s-day"><div class="s-dv">{{ num(p.absent_days) }}</div><div class="s-dk">Absent Days</div></div>
</div>
</div>
</div>
{%- if p.ugx %}
{%- set u = p.ugx %}
<div class="page-break" style="page-break-before: always; break-before: page;"></div>
<div class="lpl-slip">
<div class="s-head">
<div class="s-brand">{% if logo %}<img src="{{ logo }}">{% endif %}<div class="s-company">{{ v(p.company) }}</div></div>
<div class="s-title"><div class="s-big">PAY SLIP</div><div class="s-month">{{ v(p.slip_for) }}</div></div>
</div>
{%- if doc.docstatus == 0 %}
<div class="s-check">FOR CHECKING, NOT YET PAID</div>
{%- endif %}
<div class="s-who">
<div class="s-i"><div class="s-k">NAME</div><div class="s-v">{{ v(p.employee_name) }}</div></div>
<div class="s-i"><div class="s-k">DEPT</div><div class="s-v">{{ v(p.department) }}</div></div>
<div class="s-i"><div class="s-k">PAYROLL NO.</div><div class="s-v">{{ v(p.payroll_no) }}</div></div>
<div class="s-i"><div class="s-k">DESIGNATION</div><div class="s-v">{{ v(p.designation) }}</div></div>
<div class="s-i"><div class="s-k">CATEGORY</div><div class="s-v">{{ v(p.category) }}</div></div>
{%- if p.section %}
<div class="s-i"><div class="s-k">SECTION</div><div class="s-v">{{ v(p.section) }}</div></div>
{%- endif %}
</div>
<div class="s-money">
<div class="s-r s-th"><div class="s-n">PAYMENTS</div><div class="s-a">AMOUNT UGX</div></div>
<div class="s-r"><div class="s-n">{{ v(u.basic_label) }}</div><div class="s-a">{{ shs(u.net) }}</div></div>
<div class="s-r"><div class="s-n">ALLOWANCE</div><div class="s-a">{{ shs(u.allowance) }}</div></div>
<div class="s-r s-total"><div class="s-n">TOTAL NET</div><div class="s-a">{{ shs(u.total_net) }}</div></div>
<div class="s-r"><div class="s-n">GROSS</div><div class="s-a">{{ shs(u.gross) }}</div></div>
<div class="s-r"><div class="s-n">LST</div><div class="s-a">{{ shs(u.lst) }}</div></div>
<div class="s-r s-total"><div class="s-n">TOTAL GROSS</div><div class="s-a">{{ shs(u.total_gross) }}</div></div>
</div>
<div class="s-money">
<div class="s-r s-th"><div class="s-n">DEDUCTIONS</div><div class="s-a">AMOUNT UGX</div></div>
<div class="s-r"><div class="s-n">PAYE</div><div class="s-a">{{ shs(u.paye) }}</div></div>
<div class="s-r"><div class="s-n">NSSF 5%</div><div class="s-a">{{ shs(u.nssf_5) }}</div></div>
<div class="s-r"><div class="s-n">LST</div><div class="s-a">{{ shs(u.lst) }}</div></div>
<div class="s-r"><div class="s-n">ADVANCE</div><div class="s-a">{{ shs(u.advance) }}</div></div>
<div class="s-r s-total"><div class="s-n">T.D</div><div class="s-a">{{ shs(u.deductions) }}</div></div>
</div>
<div class="s-net">
<div class="s-l"><div class="s-nk">NET PAY UGX</div><div class="s-nv">{{ shs(u.net_pay) }}</div></div>
<div class="s-l s-round"><div class="s-nk">PAID {{ v(u.currency) }}</div><div class="s-nv">{{ money(u.paid) }}</div></div>
</div>
{%- if p.payment_by %}
<div class="s-by"><div class="s-k">PAYMENT BY</div><div class="s-v">{{ v(p.payment_by) }}</div></div>
{%- endif %}
</div>
{%- endif %}
